__global__ void linear_relu_kernel(const float* input, const float* weight, const float* bias, float* output,
                                   int input_features, int output_features, int batch_size) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid < batch_size * output_features) {
        int row = tid / output_features;
        int col = tid % output_features;
        float sum = bias[col];

        for (int i = 0; i < input_features; ++i) {
            sum += input[row * input_features + i] * weight[col * input_features + i];
        }
        output[tid] = fmaxf(sum, 0.0f);
    }
}

torch::Tensor linear_relu_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    int batch_size = input.size(0);
    int input_features = input.size(1);
    int output_features = weight.size(0);

    auto output = torch::zeros({batch_size, output_features}, input.options());
    int num_threads = 256;
    int num_blocks = (batch_size * output_features + num_threads - 1) / num_threads;

    linear_relu_kernel<<<num_blocks, num_threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        input_features,
        output_features,
        batch_size
    );

    return output;
}

