#define CEIL_DIV(a, b) ((a + b - 1) / b)

__global__ void squeeze_relu_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int B, int C_in, int C_out, int H, int W
){
    int th = blockIdx.x * blockDim.x + threadIdx.x;
    int h = th / W;
    int w = th % W;
    int c = blockIdx.y;
    int b = blockIdx.z;

    if(b >= B || c >= C_out || h >= H || w >= W) return;

    float sum = bias[c];
    for(int ic=0; ic<C_in; ic++) {
        sum += input[b*C_in*H*W + ic*H*W + h*W + w] * weight[c*C_in + ic];
    }
    output[b*C_out*H*W + c*H*W + h*W + w] = fmaxf(sum, 0.0f);
}

__global__ void fused_expand_kernel(
    const float* squeezed,
    const float* expand1x1_w,
    const float* expand1x1_b,
    const float* expand3x3_w,
    const float* expand3x3_b,
    float* output,
    int B, int C_sq, int H, int W,
    int C_e1, int C_e3
){
    int th = blockIdx.x * blockDim.x + threadIdx.x;
    int h = th / W;
    int w = th % W;
    int c = blockIdx.y;
    int b = blockIdx.z;

    if(b >= B || h >= H || w >= W) return;

    float* out_ptr = output + b*(C_e1+C_e3)*H*W + h*W + w;

    // Process expand1x1 branch
    if(c < C_e1) {
        float sum = expand1x1_b[c];
        for(int sc=0; sc<C_sq; sc++) {
            sum += squeezed[b*C_sq*H*W + sc*H*W + h*W + w] * expand1x1_w[c*C_sq + sc];
        }
        out_ptr[c*H*W] = fmaxf(sum, 0.0f);
    }

    // Process expand3x3 branch
    if(c < C_e3) {
        float sum = expand3x3_b[c];
        for(int dy=-1; dy<=1; dy++) {
            for(int dx=-1; dx<=1; dx++) {
                int h_in = h + dy;
                int w_in = w + dx;
                if(h_in>=0 && h_in<H && w_in>=0 && w_in<W) {
                    for(int sc=0; sc<C_sq; sc++) {
                        float val = squeezed[b*C_sq*H*W + sc*H*W + h_in*W + w_in];
                        int kernel_idx = dy+1 + (dx+1)*3 + sc*9 + c*9*C_sq;
                        sum += val * expand3x3_w[c*C_sq*9 + sc*9 + (dy+1)*3 + (dx+1)];
                    }
                }
            }
        }
        out_ptr[(C_e1 + c)*H*W] = fmaxf(sum, 0.0f);
    }
}

torch::Tensor squeeze_op(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias
){
    auto B = input.size(0);
    int C_in = weight.size(1);
    int C_sq = weight.size(0);
    int H = input.size(2);
    int W = input.size(3);
    auto output = torch::empty({B, C_sq, H, W}, input.options());

    dim3 threads(256,1,1);
    dim3 blocks(CEIL_DIV(H*W,256), C_sq, B);

    hipLaunchKernelGGL(squeeze_relu_kernel, blocks, threads, 0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        B, C_in, C_sq, H, W
    );

    return output;
}

torch::Tensor expand_op(
    torch::Tensor squeezed,
    torch::Tensor expand1x1_w,
    torch::Tensor expand1x1_b,
    torch::Tensor expand3x3_w,
    torch::Tensor expand3x3_b,
    int C_e1, int C_e3
){
    auto B = squeezed.size(0);
    int C_sq = squeezed.size(1);
    int H = squeezed.size(2);
    int W = squeezed.size(3);
    auto output = torch::empty({B, C_e1 + C_e3, H, W}, squeezed.options());

    dim3 threads(256,1,1);
    dim3 blocks(CEIL_DIV(H*W,256), std::max(C_e1, C_e3), B);

    hipLaunchKernelGGL(fused_expand_kernel, blocks, threads, 0, 0,
        squeezed.data_ptr<float>(),
        expand1x1_w.data_ptr<float>(),
        expand1x1_b.data_ptr<float>(),
        expand3x3_w.data_ptr<float>(),
        expand3x3_b.data_ptr<float>(),
        output.data_ptr<float>(),
        B, C_sq, H, W,
        C_e1, C_e3
    );

    return output;
}

