#define CHECK_HIP_ERROR(err) do { if (err != hipSuccess) { throw std::runtime_error(hipGetErrorString(err)); } } while (0)

__global__ void fused_bn_relu_conv_3x3_kernel(
    const float* input, const float* gamma, const float* beta,
    const float* mean, const float* var, float epsilon,
    const float* conv_weight, float* output,
    int N, int in_C, int H, int W, int out_C) {

    const int n = blockIdx.z;
    const int h = blockIdx.y * blockDim.y + threadIdx.y;
    const int w = blockIdx.x * blockDim.x + threadIdx.x;

    if (n >= N || h >= H || w >= W) return;

    for (int c_out = 0; c_out < out_C; ++c_out) {
        float sum = 0.0f;

        for (int kh = -1; kh <= 1; ++kh) {
            for (int kw = -1; kw <= 1; ++kw) {
                const int h_in = h + kh;
                const int w_in = w + kw;

                if (h_in >= 0 && h_in < H && w_in >= 0 && w_in < W) {
                    for (int c_in = 0; c_in < in_C; ++c_in) {
                        const int input_idx = ((n * in_C + c_in) * H + h_in) * W + w_in;
                        float val = input[input_idx];

                        // Normalization using batch statistics
                        float m = mean[c_in];
                        float v = var[c_in];
                        val = (val - m) / sqrt(v + epsilon) * gamma[c_in] + beta[c_in];

                        // ReLU activation
                        val = fmaxf(val, 0.0f);

                        // Convolution weights access
                        int weight_idx = ((c_out * in_C + c_in) * 3 + (kh + 1)) * 3 + (kw + 1);
                        sum += val * conv_weight[weight_idx];
                    }
                }
            }
        }

        const int output_idx = ((n * out_C + c_out) * H + h) * W + w;
        output[output_idx] = sum;
    }
}

torch::Tensor fused_bn_relu_conv_3x3_rocm(
    torch::Tensor input, torch::Tensor gamma, torch::Tensor beta,
    torch::Tensor mean, torch::Tensor var, float eps,
    torch::Tensor conv_weight) {

    auto N = input.size(0);
    auto in_C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);
    auto out_C = conv_weight.size(0);

    auto output = torch::zeros({N, out_C, H, W}, input.options());

    dim3 block(16, 16);
    dim3 grid((W + block.x - 1)/block.x, (H + block.y - 1)/block.y, N);

    hipStream_t stream = at::hip::getCurrentHIPStream();
    fused_bn_relu_conv_3x3_kernel<<<grid, block, 0, stream>>>(
        input.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(),
        mean.data_ptr<float>(), var.data_ptr<float>(), eps,
        conv_weight.data_ptr<float>(), output.data_ptr<float>(),
        N, in_C, H, W, out_C);

    CHECK_HIP_ERROR(hipGetLastError());
    CHECK_HIP_ERROR(hipStreamSynchronize(stream));

    return output;
}

