#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_assignment_kernel(
    const float* x, const float* clusters,
    const float* bn_weight, const float* bn_bias,
    const float* bn_mean, const float* bn_var, float eps,
    float* out, int B, int N, int D, int K, int G, float init_sc) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_samples = B * N;
    if (idx >= total_samples) return;

    const float* x_row = x + idx * D;
    float* out_row = out + idx * K;

    // Compute matrix multiplication with clusters (D x (K+G))
    for (int k = 0; k < K; k++) {
        float val = 0.0f;
        for (int d = 0; d < D; d++) {
            val += x_row[d] * clusters[d * (K + G) + k];
        }

        // Apply batch norm
        float mean = bn_mean[k];
        float var = bn_var[k];
        float weight = bn_weight[k];
        float bias = bn_bias[k];
        val = (val - mean) / sqrtf(var + eps);
        val = val * weight + bias;

        // Store before softmax for parallel reduction
        out_row[k] = val;
    }

    // Softmax
    float max_val = -INFINITY;
    for (int k = 0; k < K; k++) {
        max_val = max(max_val, out_row[k]);
    }

    float sum = 0.0f;
    for (int k = 0; k < K; k++) {
        out_row[k] = exp(out_row[k] - max_val);
        sum += out_row[k];
    }

    for (int k = 0; k < K; k++) {
        out_row[k] /= sum;
    }
}

torch::Tensor fused_assignment_rocm(
    torch::Tensor x, torch::Tensor clusters,
    torch::Tensor bn_weight, torch::Tensor bn_bias,
    torch::Tensor bn_mean, torch::Tensor bn_var,
    int B, int N, int D, int K, int G, float eps) {

    auto out = torch::zeros({B*N, K}, x.options());
    int total_samples = B * N;
    int block_size = 256;
    int num_blocks = (total_samples + block_size - 1) / block_size;

    fused_assignment_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        clusters.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        bn_mean.data_ptr<float>(),
        bn_var.data_ptr<float>(),
        eps,
        out.data_ptr<float>(),
        B, N, D, K, G, 1.0f);

    return out;
}

