__global__ void channel_shuffle_kernel(const float* input, float* output, int batch_size, int channels, int height, int width, int groups) {
    int cpg = channels / groups;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int size = batch_size * channels * height * width;

    if (idx >= size) return;

    int n = idx / (channels * height * width);
    int c = (idx / (height * width)) % channels;
    int h = (idx / width) % height;
    int w = idx % width;

    int orig_group = c / cpg;
    int orig_pos = c % cpg;
    int new_c = orig_pos * groups + orig_group;

    int out_idx = n * channels * height * width + new_c * height * width + h * width + w;
    output[out_idx] = input[idx];
}

torch::Tensor channel_shuffle_rocm(torch::Tensor x, int groups) {
    auto batch_size = x.size(0);
    int channels = x.size(1);
    int height = x.size(2);
    int width = x.size(3);
    auto out = torch::zeros_like(x);
    int size = batch_size * channels * height * width;

    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(channel_shuffle_kernel, 
        dim3(num_blocks), dim3(block_size), 0, 0,
        x.data_ptr<float>(), out.data_ptr<float>(), 
        batch_size, channels, height, width, groups);

    return out;
}

