using namespace torch;

template <typename scalar_t>
__global__ void fused_conv_relu_kernel(
    const scalar_t* input, const scalar_t* weight, const scalar_t* bias,
    scalar_t* output, int batch, int in_channels, int out_channels, int kernel_size, 
    int stride, int padding, int input_h, int input_w, int output_h, int output_w) {

    int global_idx = blockIdx.z;
    int batch_idx = global_idx / out_channels;
    int c_out = global_idx % out_channels;

    int h_out = blockIdx.y * blockDim.y + threadIdx.y;
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;

    if (batch_idx >= batch || c_out >= out_channels || h_out >= output_h || w_out >= output_w) return;

    scalar_t sum = bias ? bias[c_out] : 0;

    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            int h_in = h_out * stride - padding + kh;
            int w_in = w_out * stride - padding + kw;
            if (h_in >= 0 && h_in < input_h && w_in >= 0 && w_in < input_w) {
                for (int c_in = 0; c_in < in_channels; ++c_in) {
                    int idx_in = batch_idx * in_channels * input_h * input_w + 
                                 c_in * input_h * input_w + h_in * input_w + w_in;
                    int idx_w = c_out * in_channels * kernel_size * kernel_size + 
                               c_in * kernel_size * kernel_size + kh * kernel_size + kw;
                    sum += input[idx_in] * weight[idx_w];
                }
            }
        }
    }

    int idx_out = batch_idx * out_channels * output_h * output_w + 
                  c_out * output_h * output_w + h_out * output_w + w_out;
    output[idx_out] = sum > 0 ? sum : 0;
}

torch::Tensor fused_conv_relu(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int stride, int padding, int kernel_size) {

    int batch = input.size(0);
    int in_c = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);
    int out_c = weight.size(0);

    int out_h = (in_h + 2 * padding - kernel_size) / stride + 1;
    int out_w = (in_w + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch, out_c, out_h, out_w}, input.options());

    dim3 block(16, 16);
    int grid_z = batch * out_c;
    dim3 grid((out_w + block.x - 1) / block.x, (out_h + block.y - 1) / block.y, grid_z);

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "conv_relu", [&] {
        fused_conv_relu_kernel<scalar_t><<<grid, block>>>(
            input.data_ptr<scalar_t>(), weight.data_ptr<scalar_t>(),
            bias.defined() ? bias.data_ptr<scalar_t>() : nullptr,
            output.data_ptr<scalar_t>(), batch, in_c, out_c, kernel_size,
            stride, padding, in_h, in_w, out_h, out_w);
    });

    return output;
}

