    }
}

torch::Tensor elementwise_add_relu_rocm(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.sizes() == b.sizes(), "Tensor dimensions must match");
    auto out = torch::empty_like(a);
    int64_t numel = a.numel();

    const int threads = 512;
    int blocks = (numel + threads - 1) / threads;

    hipLaunchKernelGGL(add_relu_kernel, blocks, threads, 0, 0, 
        a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), numel);

    return out.clone();
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void bias_relu_kernel(const float* input, const float* bias, float* output, int num_elements, int hidden_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        int j = idx % hidden_size;
        output[idx] = fmaxf(input[idx] + bias[j], 0.0f);
    }
}

torch::Tensor bias_relu_rocm(torch::Tensor input, torch::Tensor bias) {
    int num_elements = input.numel();
    int hidden_size = bias.size(0);
    auto output = torch::empty_like(input);

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(bias_relu_kernel, 
        grid_size, block_size, 0, at::hip::getCurrentHIPStream(), 
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        hidden_size
    );

    return output;
}

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>

template <typename scalar_t>
__global__ void fused_lstm_fc_kernel(
    const scalar_t* __restrict__ lstm_out,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int batch_size,
    int seq_length,
    int hidden_size,
    int output_size) {

    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= batch_size * output_size) return;

    int batch_idx = tid / output_size;
    int out_idx = tid % output_size;

    const scalar_t* hidden = &lstm_out[batch_idx * seq_length * hidden_size + (seq_length - 1) * hidden_size];
    const scalar_t* w = &weight[out_idx * hidden_size];

    scalar_t sum = 0.0f;
    #pragma unroll
    for(int k = 0; k < hidden_size; ++k) {
        sum += hidden[k] * w[k];
    }
    sum += bias[out_idx];

    output[tid] = sum;
}

torch::Tensor fused_lstm_fc_rocm(torch::Tensor lstm_out, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(lstm_out.is_contiguous(), "LSTM output must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "Weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "Bias must be contiguous");

    auto batch_size = lstm_out.size(0);
    auto output_size = weight.size(0);

    auto output = torch::empty({batch_size, output_size}, lstm_out.options());

    const int threads = 256;
    int blocks = (batch_size * output_size + threads - 1) / threads;

    hipStream_t stream = at::cuda::getCurrentCUDAStream();
    AT_DISPATCH_FLOATING_TYPES(
        lstm_out.scalar_type(), "fused_lstm_fc", [&] {
            fused_lstm_fc_kernel<scalar_t><<<blocks, threads, 0, stream>>>(
                lstm_out.data_ptr<scalar_t>(),
                weight.data_ptr<scalar_t>(),
                bias.data_ptr<scalar_t>(),
                output.data_ptr<scalar_t>(),
                batch_size,
                lstm_out.size(1),
                lstm_out.size(2),
                output_size
            );
        }
    );
    return output;
}
